SELECT

FROM card c


    AND c.name LIKE CONCAT('%', #{query.keyword}, '%')

  AND c.series_id = #{query.seriesId}
  AND c.max_rarity = #{query.maxRarity}
  AND c.attribute = #{query.attribute}
  AND c.status = #{query.status}

    AND c.id IN (
    SELECT card_id FROM card_person_rel WHERE person_id = #{query.personId}
    )


ORDER BY c.first_pool_time DESC, c.id DESC

SELECT COUNT(*) FROM card
WHERE name = #{name}
AND id != #{excludeId}

