name = #{name}, series_id = #{seriesId}, category = #{category}, max_rarity = #{maxRarity}, first_pool_time = #{firstPoolTime}, attribute = #{attribute}, skill_desc = #{skillDesc}, attached_story_type = #{attachedStoryType}, costume_type = #{costumeType}, chibi_id = #{chibiId}, costume_id = #{costumeId}, status = #{status}, reviewer_id = #{reviewerId}, review_time = #{reviewTime}, review_remark = #{reviewRemark},
WHERE id = #{id}
